CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL DEFAULT '', display_name text NOT NULL DEFAULT '', email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'WORKER' CHECK (role IN ('WORKER','CONTRACTOR','ADMIN','SUPER_ADMIN')), organization_id uuid REFERENCES organizations(id), onboarding_path text, force_password_change boolean NOT NULL DEFAULT false, membership_status text NOT NULL DEFAULT 'NONE', membership_started_at timestamptz, membership_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS passports (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', location text DEFAULT '', travel_radius text DEFAULT '', trade text DEFAULT '', worker_type text DEFAULT 'Individual', crew_size text DEFAULT '1', years_experience text DEFAULT '', skills text DEFAULT '', availability text DEFAULT 'Available now', tools text DEFAULT '', transportation text DEFAULT '', history jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL, original_name text NOT NULL, stored_name text NOT NULL, status text NOT NULL DEFAULT 'Pending Verification', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, mfa_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS memberships (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, stripe_customer_id text, stripe_subscription_id text UNIQUE, status text NOT NULL DEFAULT 'NONE', current_period_end timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS subscription_events (event_id text PRIMARY KEY, event_type text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_memberships (company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'MEMBER', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,user_id));
INSERT INTO roles(name) VALUES ('WORKER'),('CONTRACTOR'),('ADMIN'),('SUPER_ADMIN') ON CONFLICT(name) DO NOTHING;
